<script setup lang="ts">
import {reactive,ref} from 'vue';import {request,waitJob,errorText} from '../api';import {saveAndTestMailbox} from '../settings';const emit=defineEmits<{connected:[tested:boolean]}>();const address=ref(''),code=ref(''),range=ref('14'),busy=ref(false),error=ref(''),saved=reactive({accountId:''});
async function save(){busy.value=true;error.value='';let tested=false;try{await saveAndTestMailbox(saved,{address:address.value,code:code.value,initialScan:range.value},request,waitJob);tested=true;}catch(e){error.value=errorText(e);}finally{busy.value=false;code.value='';if(saved.accountId)emit('connected',tested);}}
</script>
<template><form @submit.prevent="save" class="account-form"><label>QQ 邮箱地址<input v-model="address" type="email" placeholder="你的邮箱@qq.com" required autocomplete="username"/></label><label>邮箱授权码<input v-model="code" type="password" placeholder="请输入 IMAP 授权码" required autocomplete="new-password"/></label><p class="field-help">在 QQ 邮箱网页版「设置 → 账户」中开启 IMAP 并获取授权码。这里不需要 QQ 登录密码。</p><label>首次查看的邮件范围<select v-model="range"><option value="14">最近 14 天</option><option value="30">最近 30 天</option><option value="now">从现在开始</option></select></label><p v-if="error" class="error-box" role="alert">{{error}}</p><button class="button primary" :disabled="busy">{{busy?'正在测试连接…':'安全保存并测试连接'}}</button></form></template>
